import{_ as n,o as t,c as r,a2 as i}from"./chunks/framework.mRCPFc5l.js";const c=JSON.parse('{"title":"Was ist ein Flow","description":"Automatisierte Abläufe in ApptiveGrid — Aufbau aus Auslöser, Aktionen und Helfern.","frontmatter":{"title":"Was ist ein Flow","description":"Automatisierte Abläufe in ApptiveGrid — Aufbau aus Auslöser, Aktionen und Helfern."},"headers":[],"relativePath":"flows/was-ist-ein-flow.md","filePath":"flows/was-ist-ein-flow.md","lastUpdated":1786518403000}'),a={name:"flows/was-ist-ein-flow.md"};function s(l,e,o,d,u,h){return t(),r("div",null,[...e[0]||(e[0]=[i(`<h1 id="was-ist-ein-flow" tabindex="-1">Was ist ein Flow <a class="header-anchor" href="#was-ist-ein-flow" aria-label="Permalink to &quot;Was ist ein Flow&quot;">​</a></h1><p>Ein <strong>Flow</strong> ist ein automatisierter Ablauf. Er reagiert auf ein Ereignis und führt danach eine Reihe von Schritten aus — ohne dass jemand eingreifen muss.</p><p>Der Leerzustand im Flow-Bereich bringt es auf den Punkt: <em>Automatisiere deine Arbeit.</em></p><h2 id="aufbau" tabindex="-1">Aufbau <a class="header-anchor" href="#aufbau" aria-label="Permalink to &quot;Aufbau&quot;">​</a></h2><p>Jeder Flow besteht aus <strong>Schritten</strong>, die durch Verbindungen verkettet sind. Es gibt drei Arten, die im Editor auch so gruppiert sind:</p><table tabindex="0"><thead><tr><th>Art</th><th>Reiter</th><th>Rolle</th></tr></thead><tbody><tr><td><strong>Auslöser</strong></td><td><em>Auslöser</em></td><td>Das Ereignis, das den Flow startet</td></tr><tr><td><strong>Aktionen</strong></td><td><em>Aktionen</em></td><td>Was der Flow tut</td></tr><tr><td><strong>Helfer</strong></td><td><em>Helfer</em></td><td>Steuern den Ablauf: verzweigen, wiederholen, warten</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Genau ein Auslöser je Flow</p><p>Ein Flow hat immer genau einen Auslöser. Ist bereits einer gesetzt, meldet der Editor <em>Der Flow hat bereits einen Auslöser</em> und springt beim Hinzufügen direkt zum Reiter <em>Aktionen</em>.</p><p>Soll derselbe Ablauf auf mehrere Ereignisse reagieren, brauchen Sie mehrere Flows.</p></div><h2 id="ein-einfaches-beispiel" tabindex="-1">Ein einfaches Beispiel <a class="header-anchor" href="#ein-einfaches-beispiel" aria-label="Permalink to &quot;Ein einfaches Beispiel&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Auslöser: Eintrag per Formular</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Aktion:   E-Mail  →  Bestätigung an die anmeldende Person</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Aktion:   Eintrag aktualisieren  →  Status auf „Bestätigt&quot; setzen</span></span></code></pre></div><p>Sobald jemand das Anmeldeformular absendet, läuft der Flow los: Bestätigungsmail raus, Status im Grid setzen. Fertig.</p><h2 id="was-ein-flow-auslosen-kann" tabindex="-1">Was ein Flow auslösen kann <a class="header-anchor" href="#was-ein-flow-auslosen-kann" aria-label="Permalink to &quot;Was ein Flow auslösen kann&quot;">​</a></h2><p>Sechs Auslöser stehen zur Verfügung:</p><table tabindex="0"><thead><tr><th>Auslöser</th><th>Startet, wenn …</th></tr></thead><tbody><tr><td><strong>Neuer Eintrag</strong></td><td>ein Eintrag in einem Grid angelegt wird</td></tr><tr><td><strong>Eintrag wurde geändert</strong></td><td>ein bestehender Eintrag geändert wird</td></tr><tr><td><strong>Eintrag per Formular</strong></td><td>ein Formular einen neuen Eintrag anlegt</td></tr><tr><td><strong>Eintrag per Formular geändert</strong></td><td>ein Formular einen Eintrag ändert</td></tr><tr><td><strong>Webhook</strong></td><td>ein fremdes System eine Anfrage schickt</td></tr><tr><td><strong>Seite anzeigen</strong></td><td>eine Seite geöffnet und abgesendet wird</td></tr></tbody></table><p>→ <a href="/flows/trigger">Trigger</a></p><h2 id="was-ein-flow-tun-kann" tabindex="-1">Was ein Flow tun kann <a class="header-anchor" href="#was-ein-flow-tun-kann" aria-label="Permalink to &quot;Was ein Flow tun kann&quot;">​</a></h2><p>Grob in vier Gruppen:</p><p><strong>Mit eigenen Daten arbeiten</strong> — Eintrag erstellen, Eintrag aktualisieren, alle Einträge eines Grids laden</p><p><strong>Nach außen kommunizieren</strong> — E-Mail senden, HTTP-Anfrage senden, Slack, MS Teams, Firebase, Hubspot, SMS</p><p><strong>Dateien und Inhalte erzeugen</strong> — QR-Code, PDF zu Text, URL zu PDF, CSV-Datei importieren, Sprache zu Text, Kalendereintrag</p><p><strong>Mit Menschen interagieren</strong> — Seite anzeigen, Link zu einer Seite erstellen, vorausgefüllter Formularlink</p><p>→ <a href="/flows/aktionen">Aktionen</a></p><h2 id="ablauf-steuern" tabindex="-1">Ablauf steuern <a class="header-anchor" href="#ablauf-steuern" aria-label="Permalink to &quot;Ablauf steuern&quot;">​</a></h2><p>Vier Helfer:</p><ul><li><strong>Router</strong> — <em>Verschiedene Wege gehen</em>: verzweigt den Ablauf nach Bedingungen</li><li><strong>Parallel</strong> — <em>Führt nachfolgende Schritte für jedes Listenelement einzeln aus</em>: die Schleife über eine Liste</li><li><strong>Durchläufe zusammenführen</strong> — <em>Wartet auf alle Listendurchläufe und führt den Flow anschließend fort</em></li><li><strong>Warten</strong> — <em>Pausiert den Flow für eine festgelegte Dauer</em></li></ul><p>→ <a href="/flows/router-und-parallel">Router und Parallel</a></p><h2 id="daten-fließen-von-schritt-zu-schritt" tabindex="-1">Daten fließen von Schritt zu Schritt <a class="header-anchor" href="#daten-fließen-von-schritt-zu-schritt" aria-label="Permalink to &quot;Daten fließen von Schritt zu Schritt&quot;">​</a></h2><p>Jeder Schritt kann auf die Ergebnisse der vorherigen zugreifen. Im Schritt-Editor führt der Hinweis <em>Werte aus vorherigen Schritten verwenden</em> zur Auswahl.</p><p>Das ist das Grundprinzip: Der Auslöser liefert einen Eintrag, die erste Aktion arbeitet damit, die zweite nutzt deren Ergebnis, und so weiter.</p><p>→ <a href="/flows/daten-zwischen-schritten">Daten zwischen Schritten</a></p><h2 id="flow-und-durchlauf" tabindex="-1">Flow und Durchlauf <a class="header-anchor" href="#flow-und-durchlauf" aria-label="Permalink to &quot;Flow und Durchlauf&quot;">​</a></h2><p>Zwei Begriffe, die leicht durcheinandergehen:</p><ul><li>Der <strong>Flow</strong> ist der Bauplan — das, was Sie im Editor bearbeiten.</li><li>Ein <strong>Durchlauf</strong> ist eine einzelne Ausführung. Die Oberfläche nennt das <em>Vorherige Ausführungen</em>.</li></ul><p>Jeder Durchlauf hat einen eigenen Status (<em>Fertig</em>, <em>Fehler</em>, <em>Wartet</em>), eine Dauer und eine Anzahl ausgeführter Schritte.</p><p>→ <a href="/flows/durchlaufhistorie">Durchlaufhistorie</a></p><h2 id="wo-flows-liegen" tabindex="-1">Wo Flows liegen <a class="header-anchor" href="#wo-flows-liegen" aria-label="Permalink to &quot;Wo Flows liegen&quot;">​</a></h2><p>Flows gehören zu einem <strong>Space</strong>, nicht zu einem einzelnen Grid — auch wenn ihr Auslöser sich auf ein Grid bezieht. Sie finden sie in der Seitenleiste unter <strong>Flows</strong>.</p><p>Der Editor hat zwei Reiter: <strong>Editor</strong> zum Bauen und <strong>Verlauf</strong> für vergangene Durchläufe.</p><div class="warning custom-block"><p class="custom-block-title">Anzahl der Flows ist tarifabhängig</p><p>Wie viele Flows ein Space enthalten darf, hängt vom Tarif ab. Einige besonders leistungsfähige Schritte sind zusätzlich dem höchsten Tarif vorbehalten und im Editor mit <strong>Pro</strong> gekennzeichnet.</p></div><h2 id="ein-und-ausschalten" tabindex="-1">Ein- und ausschalten <a class="header-anchor" href="#ein-und-ausschalten" aria-label="Permalink to &quot;Ein- und ausschalten&quot;">​</a></h2><p>Jeder Flow hat einen <strong>Schalter</strong>. Steht er auf <em>aus</em>, bleibt der Flow mit allen Schritten erhalten, reagiert aber auf kein Ereignis mehr.</p><p>Sie finden ihn an zwei Stellen:</p><ul><li>in der Liste unter <strong>Flows</strong> rechts neben jedem Eintrag</li><li>im Flow selbst rechts neben den Reitern <em>Editor</em> und <em>Verlauf</em></li></ul><p>Ein neu angelegter Flow ist eingeschaltet.</p><div class="tip custom-block"><p class="custom-block-title">Ausschalten ist die sanfte Bremse</p><p>Vor einem größeren <a href="/grids/csv-import">CSV-Import</a> oder beim Aufräumen eines <a href="/ansichten/kanban">Kanban-Boards</a> müssen Sie den Auslöser nicht umbauen — schalten Sie den betroffenen Flow kurz aus und danach wieder ein.</p><p>Auch beim Umbau eines produktiven Flows sinnvoll: Solange er aus ist, laufen keine halbfertigen Konfigurationen gegen echte Daten.</p></div><div class="warning custom-block"><p class="custom-block-title">Ausschalten hält auch laufende Ausführungen an</p><p>Ausführungen, die gerade laufen oder auf eine Seiteneingabe warten, werden nach dem Ausschalten nicht fortgesetzt. Sie bleiben stehen, wo sie sind.</p></div><p>Den Schalter bedienen dürfen nur Personen mit der Rolle <strong>Managen</strong> und der Eigentümer. Bei <strong>Bearbeiten</strong> und <strong>Ansehen</strong> ist er sichtbar, aber nicht bedienbar.</p><p>ApptiveGrid schaltet einen Flow auch selbst aus, wenn er dreimal hintereinander am selben Fehler scheitert → <a href="/flows/durchlaufhistorie#benachrichtigung-bei-fehlern">Durchlaufhistorie</a></p><h2 id="wann-ein-flow-das-richtige-werkzeug-ist" tabindex="-1">Wann ein Flow das richtige Werkzeug ist <a class="header-anchor" href="#wann-ein-flow-das-richtige-werkzeug-ist" aria-label="Permalink to &quot;Wann ein Flow das richtige Werkzeug ist&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aufgabe</th><th>Besser geeignet</th></tr></thead><tbody><tr><td>Nach jeder Anmeldung eine Bestätigung senden</td><td><strong>Flow</strong></td></tr><tr><td>Einen Wert aus einem verknüpften Eintrag anzeigen</td><td>Spaltentyp <a href="/referenz/spaltentypen">Wert übernehmen</a></td></tr><tr><td>Eine Summe über verknüpfte Einträge bilden</td><td>Spaltentyp <a href="/referenz/spaltentypen">Summe berechnen</a></td></tr><tr><td>Nur bestimmte Einträge anzeigen</td><td><a href="/ansichten/filtern-sortieren-gruppieren">Filter in einer Ansicht</a></td></tr><tr><td>Daten an ein anderes System melden</td><td><strong>Flow</strong> oder <a href="/integrationen/webhooks">Webhook</a></td></tr><tr><td>Mehrstufigen Genehmigungsprozess abbilden</td><td><strong>Flow</strong> mit <em>Seite anzeigen</em></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Berechnung ist kein Flow</p><p>Für abgeleitete Werte innerhalb eines Eintrags sind die berechneten Spaltentypen fast immer die bessere Wahl: Sie aktualisieren sich sofort, verbrauchen keinen Flow und lassen sich nicht durch Fehler unterbrechen.</p><p>Ein Flow lohnt sich, wenn etwas <strong>passieren</strong> soll — nicht, wenn etwas nur <strong>angezeigt</strong> werden soll.</p></div><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/flows/ersten-flow-bauen">Ersten Flow bauen</a></li><li><a href="/referenz/flow-schritte">Flow-Schritte</a> — alle Schritte im Überblick</li><li><a href="/flows/trigger">Trigger</a></li><li><a href="/flows/aktionen">Aktionen</a></li><li><a href="/flows/testen">Flows testen</a></li></ul>`,52)])])}const f=n(a,[["render",s]]);export{c as __pageData,f as default};
